import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import process from 'node:process';

function isPlainObject(value){
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function validateRules(rules){
  if(!Array.isArray(rules)) throw new Error('rules must be an array');
  const seen = new Set();
  for(const rule of rules){
    if(!isPlainObject(rule)) throw new Error('each rule must be a non-null, non-array object');
    if(typeof rule.id !== 'string' || rule.id === '') throw new Error('rule.id must be a nonempty string');
    if(seen.has(rule.id)) throw new Error('rule ids must be unique');
    seen.add(rule.id);
    if(typeof rule.literal !== 'string' || rule.literal === '') throw new Error('rule.literal must be a nonempty string');
    if(typeof rule.replacement !== 'string') throw new Error('rule.replacement must be a string');
  }
}

function findMatches(text, rules){
  const matches = [];
  for(let i = 0; i < rules.length; i++){
    const {literal, id} = rules[i];
    let idx = text.indexOf(literal, 0);
    while(idx !== -1){
      matches.push({start: idx, end: idx + literal.length, id, ruleIndex: i});
      idx = text.indexOf(literal, idx + 1);
    }
  }
  return matches;
}

function selectEdits(matches){
  matches.sort((a, b) => {
    if(a.start !== b.start) return a.start - b.start;
    if(a.end !== b.end) return b.end - a.end;
    return a.ruleIndex - b.ruleIndex;
  });
  const edits = [];
  let cursor = 0;
  for(const m of matches){
    if(m.start < cursor) continue;
    edits.push({start: m.start, end: m.end, id: m.id});
    cursor = m.end;
  }
  return edits;
}

export function planRedactions(text, rules){
  if(typeof text !== 'string') throw new Error('text must be a string');
  validateRules(rules);
  const matches = findMatches(text, rules);
  const edits = selectEdits(matches);
  let out = '';
  let pos = 0;
  for(const edit of edits){
    out += text.slice(pos, edit.start);
    out += rules.find(r => r.id === edit.id).replacement;
    pos = edit.end;
  }
  out += text.slice(pos);
  return {
    text: out,
    edits,
    originalBytes: Buffer.byteLength(text, 'utf8'),
    redactedBytes: Buffer.byteLength(out, 'utf8'),
  };
}

